from __future__ import annotations

import logging
import ast
import re
import threading
import time
from dataclasses import dataclass, field

import z3

logger = logging.getLogger(__name__)

_BOOL_INDICATORS = re.compile(r'\bImplies\s*\(|==\s*True|==\s*False|\bNot\s*\(|\bAnd\s*\(|\bOr\s*\(')


def _is_boolean_formula(formula_str: str) -> bool:
    """Detect whether a formula uses boolean logic (vs arithmetic)."""
    return bool(_BOOL_INDICATORS.search(formula_str))


def _strip_nl_prefix(s: str) -> str:
    """Strip natural language prefix before a formula."""
    # Colon separator: "The constraint is: x + y == 10"
    if ':' in s:
        after = s.split(':', 1)[1].strip()
        if after and re.match(r'[a-zA-Z_\d(\-]', after):
            return after
    # Common NL lead-ins without colon: "We need X", "Since X, Y"
    m = re.match(
        r'(?:We\s+(?:need|have|get|know|require)|'
        r'(?:Since|Because|Note\s+that|Given\s+that|It\s+follows\s+that)\b'
        r')[,\s]+',
        s, re.IGNORECASE,
    )
    if m:
        candidate = s[m.end():].strip()
        if candidate and re.match(r'[a-zA-Z_\d(\-]', candidate):
            return candidate
    return s


def _needs_int_vars(formula_str: str) -> bool:
    """Detect if formula uses integer operations (%, //, Mod)."""
    return bool(re.search(r'(?<![/])%(?!%)|//|\bMod\s*\(', formula_str))


def _ast_rewrite(formula_str: str) -> str:
    """Rewrite chained comparisons and Python and/or/not to Z3 equivalents via AST."""
    try:
        tree = ast.parse(formula_str, mode='eval')
    except SyntaxError:
        return formula_str

    modified = [False]

    class _Rewriter(ast.NodeTransformer):
        def visit_Compare(self, node):
            self.generic_visit(node)
            if len(node.comparators) > 1:
                modified[0] = True
                parts = []
                left = node.left
                for op, comp in zip(node.ops, node.comparators):
                    parts.append(ast.Compare(
                        left=ast.copy_location(left, node),
                        ops=[op],
                        comparators=[comp],
                    ))
                    left = comp
                return ast.Call(
                    func=ast.Name(id='And', ctx=ast.Load()),
                    args=parts, keywords=[],
                )
            return node

        def visit_BoolOp(self, node):
            self.generic_visit(node)
            modified[0] = True
            name = 'And' if isinstance(node.op, ast.And) else 'Or'
            return ast.Call(
                func=ast.Name(id=name, ctx=ast.Load()),
                args=node.values, keywords=[],
            )

        def visit_UnaryOp(self, node):
            self.generic_visit(node)
            if isinstance(node.op, ast.Not):
                modified[0] = True
                return ast.Call(
                    func=ast.Name(id='Not', ctx=ast.Load()),
                    args=[node.operand], keywords=[],
                )
            return node
